generated_pydough:
# Count the total number of policies used by customer "Dayana Robel"
dayana_policy_count = customer.WHERE(
    customer_name == "Dayana Robel"
).CALCULATE(
    total_policies = COUNT(customers_policy)
)

# Find the maximum active_to_date across all contact channels for Tillman Ernser
latest_active_to_date = Customers.WHERE(
    customer_name == "Tillman Ernser"
).CALCULATE(
    latest_active_to_date=MAX(customer_contact_channel.active_to_date)
)

# Get names, classes, and ranks of all captains
captain_info = captains.CALCULATE(
    name=name,
    class=class,
    rank=rank
)

# Find distinct last names of students who received president votes, excluding those with advisor 2192
students_with_president_votes = voting_records.WHERE(
    president_vote != None
).CALCULATE(
    received_vote_stuid = president_vote
).PARTITION(
    name="vote_recipients", 
    by=received_vote_stuid
).CALCULATE(
    stuid = received_vote_stuid
)

# Get the last names of these students, excluding those with advisor 2192
distinct_lastnames = students.WHERE(
    (HAS(students_with_president_votes.WHERE(stuid == stuid)) == 1) &
    (advisor != 2192)
).PARTITION(
    name="lastname_groups", 
    by=lname
).CALCULATE(
    last_name = lname
)

columbus_crew_players = player.WHERE(
    team_join.name == "Columbus Crew"
).CALCULATE(
    player_name=player,
    years_played=years_played
)

# Filter customer orders before the specified datetime and sum order quantities
total_products_ordered = customers_and_addresses.CALCULATE(
    total_amount=SUM(
        customer_order.WHERE(
            order_date < "2018-03-17 07:13:53"
        ).order_item.order_quantity
    )
)

# Filter volumes by artists who are at most 25 years old and calculate average weeks on top
young_artist_volumes_avg = volumes.WHERE(
    artist.age <= 25
).CALCULATE(
    avg_weeks_on_top=AVG(weeks_on_top)
)

# Find tourist attractions visited at least twice
attractions_visited_twice = tourist_attraction.WHERE(
    HAS(visit)
).CALCULATE(
    attraction_id=tourist_attraction_id,
    attraction_name=name,
    visit_count=COUNT(visit)
).WHERE(
    visit_count >= 2
).CALCULATE(
    attraction_id=attraction_id,
    attraction_name=attraction_name
)

# Filter entrepreneurs by height and calculate total money requested
result = entrepreneurs.WHERE(
    person.height > 1.85
).CALCULATE(
    total_money_requested = SUM(money_requested)
)

# Get elimination times for wrestlers who held their title for more than 50 days
elimination_times = eliminations.WHERE(
    wrestler.days_held > '50'
).CALCULATE(
    time=time
)

# Find employees who do not work in departments with managers having ids between 100 and 200
employees_not_in_managed_depts = employee.WHERE(
    ~ISIN(department_id, department.WHERE(
        (manager_id >= "100") & (manager_id <= "200")
    ).SELECT(department_id))
)

# Find countries with surface area greater than any European country
min_europe_surface = world_1.countries.WHERE(continent == "Europe").CALCULATE(
    min_area = MIN(CAST(surfacearea, "float64"))
)

result = world_1.countries.WHERE(
    CAST(surfacearea, "float64") > min_europe_surface.SINGULAR().min_area
).CALCULATE(
    country_name = name
)

# Find the minimum population among Asian countries
min_asian_population = world_1.countries.WHERE(continent == "Asia").CALCULATE(
    min_pop=MIN(population)
).min_pop.SINGULAR()

# Find African countries with population smaller than the minimum Asian population
african_countries_smaller_than_asia = world_1.countries.WHERE(
    (continent == "Africa") & (population < min_asian_population)
).CALCULATE(
    country_name=name
)

battles_with_high_casualties = battles.WHERE(
    HAS(ships.deaths) == 1
).CALCULATE(
    battle_id=id,
    battle_name=name,
    total_killed=SUM(ships.deaths.CALCULATE(killed_num=CAST(killed, "int")).killed_num)
).WHERE(
    total_killed > 10
).CALCULATE(
    battle_id=battle_id,
    battle_name=battle_name
)

# Find the maximum fastest lap speed in Monaco Grand Prix 2008
monaco_2008_max_speed = race.WHERE(
    (year == 2008) & (name == "Monaco Grand Prix")
).result.WHERE(
    fastestlapspeed != ""
).CALCULATE(
    max_fastest_lap_speed=MAX(fastestlapspeed)
)

# Find the teacher name for the math course
math_teacher = courses.WHERE(
    course == "Math"
).course_arranges.teacher.CALCULATE(
    teacher_name=name
)

london_employees = employee.WHERE(
    department.location.city == "London"
).CALCULATE(
    full_name=JOIN_STRINGS(' ', first_name, last_name),
    salary=salary
)

london_employees = employee.WHERE(
    HAS(department) == 1
).WHERE(
    department.location_id != None
).location.WHERE(
    location_id == department.location_id
).WHERE(
    city == "London"
).department.employee.CALCULATE(
    full_name=JOIN_STRINGS(' ', first_name, last_name),
    salary=salary
)

# Count products that are never booked with amount higher than 200
result = products_for_hires.WHERE(
    HASNOT(products_bookeds.WHERE(FLOAT(booked_amount) > 200))
).CALCULATE(
    count_products = COUNT(products_for_hires)
)

storm_affected_count = storms.WHERE(
    HAS(affected_regions) == 1
).CALCULATE(
    storm_name=name,
    num_affected_regions=COUNT(affected_regions)
)

# Find parties with delegates in both "Appropriations" and "Economic Matters" committees
parties_with_both_committees = elections.WHERE(
    ISIN(committee, ("Appropriations", "Economic Matters"))
).CALCULATE(
    party_name=party_join.party,
    committee=committee
).PARTITION(name="party_groups", by=party_name).WHERE(
    HAS(elections.WHERE(committee == "Appropriations")) &
    HAS(elections.WHERE(committee == "Economic Matters"))
).CALCULATE(
    party_name=party_name
)

customers_without_accounts = customer.CALCULATE(
    num_accounts=COUNT(account)
).WHERE(
    num_accounts == 0
).CALCULATE(
    num_customers_without_account=RELCOUNT(customer_id)
)

most_recent_complaint_customer_phone = complaint.TOP_K(
    1, by=date_complaint_raised.DESC(na_pos='last')
).SINGULAR().customer.CALCULATE(
    customer_phone_number=phone_number
)
